25	// diffOpts holds the resolved options for `birdseye diff`.
26	type diffOpts struct {
27		Semantic bool
28		Plain    bool
29		CacheDir string
30	}
31	
32	const maxArchiveBytes = 50 << 20 // 50 MiB safety cap on uncompressed size
33	
34	func newDiffCmd(g *GlobalFlags) *cobra.Command {
35		o := &diffOpts{}
36		c := &cobra.Command{
37			Use:   "diff [module] [versionA] [versionB]",
38			Short: "Diff two versions of a Crow module",
39			Long: "Diff two versions of a module hosted in Crow.\n\n" +
40				"If module/versions are omitted, the interactive TUI launches\n" +
41				"(see picker task). With --plain, prints unified diff to stdout.",
42			Args:          cobra.MaximumNArgs(3),
43			SilenceUsage:  true,
44			SilenceErrors: true,
45			RunE: func(cmd *cobra.Command, args []string) error {
46				return runDiff(cmd.Context(), cmd, args, g, o)
47			},
48		}
49		c.Flags().BoolVar(&o.Semantic, "semantic", false, "include HCL-aware semantic diff alongside textual")
50		c.Flags().BoolVar(&o.Plain, "plain", false, "force plain (non-TUI) output")
51		c.Flags().BoolVar(&o.Plain, "no-tui", false, "alias for --plain")
52		c.Flags().StringVar(&o.CacheDir, "cache-dir", defaultCacheDir(), "module tarball cache directory")
53		return c
54	}
55	
56	func defaultCacheDir() string {
57		if home, err := os.UserCacheDir(); err == nil {
58			return filepath.Join(home, "birdseye")
59		}
60		return ".birdseye-cache"
61	}
62	
63	func newHTTPClient(d time.Duration) *http.Client {
64		return &http.Client{Timeout: d}
65	}
66	
67	func parseModuleAddress(s string) (api.ModuleIdentifier, error) {
68		parts := strings.Split(s, "/")
69		if len(parts) != 3 {
70			return api.ModuleIdentifier{}, fmt.Errorf("%w: module address must be namespace/name/provider, got %q", ErrUsage, s)
71		}
72		id := api.ModuleIdentifier{Namespace: parts[0], Name: parts[1], Provider: parts[2]}
73		if err := id.Validate(); err != nil {
74			return api.ModuleIdentifier{}, fmt.Errorf("%w: %v", ErrUsage, err)
75		}
76		return id, nil
77	}
78	
79	func runDiff(ctx context.Context, cmd *cobra.Command, args []string, g *GlobalFlags, o *diffOpts) error {
80		if len(args) == 0 {
81			return runInteractive(ctx, cmd, g, o)
82		}
83		if len(args) != 3 {
84			return fmt.Errorf("%w: diff requires <module> <versionA> <versionB>", ErrUsage)
85		}
86		id, err := parseModuleAddress(args[0])
87		if err != nil {
88			return err
89		}
90		if err := api.ValidateVersion(args[1]); err != nil {
91			return fmt.Errorf("%w: %v", ErrUsage, err)
92		}
93		if err := api.ValidateVersion(args[2]); err != nil {
94			return fmt.Errorf("%w: %v", ErrUsage, err)
95		}
96		modA := api.Module{ModuleIdentifier: id, Version: args[1]}
97		modB := api.Module{ModuleIdentifier: id, Version: args[2]}
98	
99		cli := client.New(g.CrowURL, client.WithHTTPClient(newHTTPClient(g.Timeout)))
100		cache, err := registry.NewDiskCache(o.CacheDir)
101		if err != nil {
102			return fmt.Errorf("cache init: %w", err)
103		}
104		reg := registry.New(cli, cache)
105	
106		aBytes, bBytes, err := reg.FetchPair(ctx, modA, modB)
107		if err != nil {
108			return err
109		}
110	
111		modAExtracted, err := archive.Extract(aBytes, maxArchiveBytes)
112		if err != nil {
113			return fmt.Errorf("%w: %v", ErrArchive, err)
114		}
115		modBExtracted, err := archive.Extract(bBytes, maxArchiveBytes)
116		if err != nil {
117			return fmt.Errorf("%w: %v", ErrArchive, err)
118		}
119	
120		result := diff.Result{Files: diff.Textual(modAExtracted, modBExtracted)}
121		// Semantic mode wired in Task 17.
122	
123		if !o.Plain && isTTY(cmd.OutOrStdout()) {
124			return tui.RunBrowser(ctx, result)
125		}
126		return renderPlain(cmd.OutOrStdout(), result)
127	}
