129	// isTTY reports whether w is a *os.File backed by a terminal.
130	func isTTY(w io.Writer) bool {
131		f, ok := w.(*os.File)
132		if !ok {
133			return false
134		}
135		return term.IsTerminal(int(f.Fd()))
136	}
137	
138	func runInteractive(ctx context.Context, cmd *cobra.Command, g *GlobalFlags, o *diffOpts) error {
139		if !isTTY(cmd.OutOrStdout()) {
140			return fmt.Errorf("%w: interactive mode requires a TTY", ErrUsage)
141		}
142		cli := client.New(g.CrowURL, client.WithHTTPClient(newHTTPClient(g.Timeout)))
143		cache, err := registry.NewDiskCache(o.CacheDir)
144		if err != nil {
145			return fmt.Errorf("cache init: %w", err)
146		}
147		reg := registry.New(cli, cache)
148	
149		// Stage 1: picker → fetched bytes
150		p := tui.NewPicker(&tui.Deps{Client: cli, Reg: reg})
151		prog := tea.NewProgram(p, tea.WithAltScreen(), tea.WithContext(ctx))
152		if _, err := prog.Run(); err != nil {
153			return err
154		}
155		aBytes, bBytes := p.Bytes()
156		if aBytes == nil || bBytes == nil {
157			// User quit before completing picker; not an error.
158			return nil
159		}
160	
161		// Stage 2: extract + diff + browser
162		modA, err := archive.Extract(aBytes, maxArchiveBytes)
163		if err != nil {
164			return fmt.Errorf("%w: %v", ErrArchive, err)
165		}
166		modB, err := archive.Extract(bBytes, maxArchiveBytes)
167		if err != nil {
168			return fmt.Errorf("%w: %v", ErrArchive, err)
169		}
170		result := diff.Result{Files: diff.Textual(modA, modB)}
171		return tui.RunBrowser(ctx, result)
172	}
173	
174	// renderPlain writes the diff result to w in unified-diff format.
175	// "no differences" is emitted when there are zero files in the result.
176	func renderPlain(w io.Writer, r diff.Result) error {
177		if len(r.Files) == 0 {
178			_, err := fmt.Fprintln(w, "no differences")
179			return err
180		}
181		for i, fd := range r.Files {
182			if i > 0 {
183				_, _ = fmt.Fprintln(w)
184			}
185			_, _ = fmt.Fprintf(w, "=== %s (%s) +%d -%d\n", fd.Path, fd.Status, fd.Adds, fd.Dels)
186			_, _ = fmt.Fprint(w, fd.Unified)
187		}
188		return nil
189	}
